action.mutation:
mutation UpdateProductionLog($payload: [ProductionLogUpdatePayloadInput!]!) {
  mutation: updateProductionLog(payload: $payload) {
    id
    code
  }
}

mutation DeleteProductionLog($payload: [ProductionLogDeletePayloadInput!]!) {
  mutation: deleteProductionLog(payload: $payload) {
    id
    code
  }
}

mutation CreateProductionLog($payload: [ProductionLogCreatePayloadInput!]!) {
  mutation: createProductionLog(payload: $payload) {
    id
    code
  }
}
